# R golden fixtures for gaply_core's Mann-Whitney and Kruskal-Wallis tests as
# an analysis (Research OS, Phase 8Y-1, decisions 602 and 604, capability
# stats.analyze.independent_ranks).
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_ranks_fixtures.R
#
# R is the reference, run outside Gaply (ADR-008): nothing of R is copied into
# Gaply. Base R only: the stats package (rank, median, wilcox.test,
# kruskal.test, pnorm, pchisq). Written with R 4.6.1, whose version the files'
# headers record.
#
# Writes, next to this script:
#   * data_*.csv: one synthetic dataset per case (a two-line '#' header, then
#     `id,y,g`), each READ BACK as Gaply reads it: read.csv with
#     strip.white = TRUE, both columns as character, "" and "NaN" as missing
#     (two of Gaply's missing tokens, stats_verify::is_missing); the outcome
#     a number where as.numeric reads one; numeric group levels plain
#     integers only, so R's text is Gaply's level code;
#   * counts_*.csv: for the cases of 100,000 rows, a list of (y, g, n) that
#     the test and this script both expand to rows the same way: each line in
#     the file's order, repeated n times;
#   * cases.tsv: each case's file, its outcome's and group's headers, the
#     included levels (their indexes in code-point order, or "all") and its
#     missing codes;
#   * expected.tsv: R's answer for every case, one number per row (case, key,
#     value), the value as %.17g; a level's label as text; "nc <code>" for a
#     number Gaply gives as not computable; "absent" for the exact p where it
#     is not given; for a refusal, the code and its parameters.
#
# A row is left out once, by the first reason found: the group empty
# (missing_group), the group a level not included (other_level), the outcome
# empty (missing_outcome), the outcome a listed code (missing_code; the
# outcome only). The group's levels are its whole column's distinct values
# in code-point order, sort(method = "radix"), whatever the locale: Gaply's
# order (decision 78), and the included levels are named by their index in
# it.
#
# Where each number comes from:
#   * the ranks: rank(ties.method = "average") over every included value,
#     together; each group's rank sum and mean rank from them; its median,
#     median(); the tie runs from table(): their count (runs of two or more)
#     and sum(t^3 - t);
#   * two groups, the Mann-Whitney test, the first group the included level
#     with the lower index: U1 is wilcox.test(first, second, exact = FALSE,
#     correct = FALSE)$statistic (W), U2 = n1 n2 - U1; the asymptotic p, its
#     p.value. z = (U1 - n1 n2 / 2) / sigma, sigma^2 = (n1 n2 / 12) ((N + 1) -
#     sum(t^3 - t) / (N (N - 1))), and the rank-biserial correlation,
#     2 U1 / (n1 n2) - 1: no base R function gives them, so THE SAME FORMULAS
#     ARE WRITTEN TWICE, here and in gaply_core; z is checked against R's p
#     (2 pnorm(-|z|) within 1e-9). The exact p is wilcox.test(exact =
#     TRUE)$p.value, asked for only when no two included values are tied and
#     each group has fewer than 50 values: R 4.6 gives a conditional exact p
#     with ties too by default, which Gaply does not give, so exact = TRUE is
#     never asked for with ties;
#   * three or more groups, the Kruskal-Wallis test: kruskal.test's statistic,
#     df and p.value, the statistic as h_kruskal_test (R's form, 12 / (N (N +
#     1)) sum R_i^2 / n_i - 3 (N + 1), over its tie correction). Gaply's H is
#     (12 / (N (N + 1))) sum (D_i^2 / n_i) / C, D_i = R_i - n_i (N + 1) / 2,
#     C = 1 - sum(t^3 - t) / (N^3 - N), which no base function gives: THE SAME
#     FORMULA IS WRITTEN TWICE, and written as h (decision 618: the mean rank
#     less (N + 1) / 2 cancels near the null, D_i does not); epsilon-squared,
#     H / (N - 1), written twice too. The golden test compares Gaply's H with
#     h and its p with kruskal.test's, gates h_kruskal_test but in kw_large,
#     and prints kw_large's difference;
#   * every included value equal: sigma and C are 0, so z and its p, and H,
#     its p and epsilon-squared, are "nc stats.ranks.all_values_tied".
#
# Synthetic data only. No manuscript or data of anyone's is read.

here <- local({
  a <- commandArgs(trailingOnly = FALSE)
  f <- sub("^--file=", "", a[grep("^--file=", a)])
  if (length(f)) dirname(normalizePath(f)) else getwd()
})
setwd(here)

HEADER <- c(
  "# Synthetic data for gaply_core's rank tests R golden fixtures (Research OS, Phase 8Y-1).",
  "# Generated by /usr/local/bin/Rscript make_ranks_fixtures.R (do not edit by hand)."
)
fmt <- function(x) if (is.character(x)) x else if (is.na(x)) "NA" else sprintf("%.17g", x)

cases <- character()
expected <- character()
emit <- function(case, key, value) {
  expected <<- c(expected, paste(case, key, fmt(value), sep = "\t"))
}
add_case <- function(case, file, outcome, group, levels, codes) {
  cases <<- c(cases, paste(case, file, outcome, group,
                           if (is.null(levels)) "all" else paste(levels, collapse = " "),
                           if (length(codes)) paste(codes, collapse = " ") else "-", sep = "\t"))
}

# A data file: the rows in a fixed shuffled order, written, then read back.
write_data <- function(name, y, g) {
  n <- length(y)
  o <- order((seq_len(n) * 7919) %% 10007, seq_len(n))
  y <- y[o]; g <- g[o]
  path <- paste0("data_", name, ".csv")
  ys <- ifelse(is.na(y), "", y); gs <- ifelse(is.na(g), "", g)
  writeLines(c(HEADER, "id,y,g", paste(seq_len(n), ys, gs, sep = ",")), path, useBytes = TRUE)
  read.csv(path, comment.char = "#", na.strings = c("", "NaN"), strip.white = TRUE,
           colClasses = c("integer", "character", "character"), encoding = "UTF-8")
}

# Each (y, g) line repeated n times, in the file's order: the expansion the
# test makes from a counts file.
write_counts <- function(name, y, g, n) {
  path <- paste0("counts_", name, ".csv")
  writeLines(c(HEADER, "y,g,n", paste(y, g, n, sep = ",")), path, useBytes = TRUE)
  data.frame(id = seq_len(sum(n)), y = rep(y, n), g = rep(g, n), stringsAsFactors = FALSE)
}

radix_levels <- function(x) sort(unique(x), method = "radix")
num <- function(x) sprintf("%.3f", x)

analyse <- function(case, d, codes = numeric(), levels = NULL, refusal = FALSE) {
  g <- d$g; y_txt <- d$y
  all_levels <- radix_levels(g[!is.na(g)])
  if (refusal) {
    k_all <- length(all_levels)
    if (k_all < 2) { emit(case, "refused", "stats.ranks.group_one_level")
      emit(case, "refused.column", "group"); emit(case, "refused.count", k_all); return(invisible()) }
    if (k_all > 50) { emit(case, "refused", "stats.ranks.too_many_levels")
      emit(case, "refused.count", k_all); emit(case, "refused.limit", 50); return(invisible()) }
  }
  inc <- if (is.null(levels)) all_levels else all_levels[levels + 1]
  missing_group <- is.na(g)
  other <- !missing_group & !(g %in% inc)
  rest <- !missing_group & !other
  y <- suppressWarnings(as.numeric(y_txt))
  missing_outcome <- rest & is.na(y_txt)
  coded <- rest & !is.na(y_txt) & y %in% codes
  keep <- rest & !is.na(y_txt) & !coded
  yk <- y[keep]; gk <- g[keep]
  k <- length(inc)
  idx <- match(inc, all_levels) - 1
  if (refusal) {
    for (j in seq_len(k)) if (sum(gk == inc[j]) == 0) {
      emit(case, "refused", "stats.ranks.group_empty"); emit(case, "refused.index", idx[j])
      return(invisible())
    }
    stop(case, ": a refusal case that R does not refuse")
  }
  stopifnot(!anyNA(yk), k >= 2)
  N <- as.numeric(length(yk))
  emit(case, "excluded.missing_group", sum(missing_group))
  emit(case, "excluded.other_level", sum(other))
  emit(case, "excluded.missing_outcome", sum(missing_outcome))
  emit(case, "excluded.missing_code", sum(coded))
  r <- rank(yk, ties.method = "average")
  tt <- as.numeric(table(yk))
  T <- sum(tt^3 - tt)
  all_tied <- length(tt) == 1
  emit(case, "n", N); emit(case, "groups", k); emit(case, "tie_runs", sum(tt >= 2))
  ns <- numeric(k); rs <- numeric(k)
  for (j in seq_len(k)) {
    at <- gk == inc[j]
    ns[j] <- sum(at); rs[j] <- sum(r[at])
    key <- function(s) sprintf("group.%d.%s", idx[j], s)
    emit(case, key("label"), inc[j])
    emit(case, key("n"), ns[j])
    emit(case, key("median"), median(yk[at]))
    emit(case, key("rank_sum"), sum(r[at]))
    emit(case, key("mean_rank"), sum(r[at]) / ns[j])
  }
  nc <- "nc stats.ranks.all_values_tied"
  if (k == 2) {
    x1 <- yk[gk == inc[1]]; x2 <- yk[gk == inc[2]]
    n1 <- as.numeric(length(x1)); n2 <- as.numeric(length(x2))
    w <- suppressWarnings(wilcox.test(x1, x2, exact = FALSE, correct = FALSE))
    W <- unname(w$statistic)
    emit(case, "mann_whitney.first", idx[1]); emit(case, "mann_whitney.second", idx[2])
    emit(case, "mann_whitney.u1", W); emit(case, "mann_whitney.u2", n1 * n2 - W)
    if (all_tied) {
      emit(case, "mann_whitney.z", nc); emit(case, "mann_whitney.p", nc)
    } else {
      sigma <- sqrt((n1 * n2 / 12) * ((N + 1) - T / (N * (N - 1))))
      z <- (W - n1 * n2 / 2) / sigma
      stopifnot(abs(2 * pnorm(-abs(z)) - w$p.value) <= 1e-9 * w$p.value)
      emit(case, "mann_whitney.z", z); emit(case, "mann_whitney.p", w$p.value)
    }
    ties <- length(tt) < N
    big <- n1 >= 50 || n2 >= 50
    if (!ties && !big) {
      emit(case, "mann_whitney.exact_p", wilcox.test(x1, x2, exact = TRUE)$p.value)
    } else {
      emit(case, "mann_whitney.exact_p", "absent")
    }
    emit(case, "mann_whitney.rank_biserial", 2 * W / (n1 * n2) - 1)
    emit(case, "note.exact_not_given_ties", as.numeric(ties))
    emit(case, "note.exact_not_given_size", as.numeric(big))
  } else {
    emit(case, "kruskal_wallis.df", k - 1)
    if (all_tied) {
      emit(case, "kruskal_wallis.h", nc); emit(case, "kruskal_wallis.p", nc)
      emit(case, "kruskal_wallis.epsilon_squared", nc)
    } else {
      kt <- kruskal.test(yk, factor(gk, levels = inc))
      stopifnot(unname(kt$parameter) == k - 1)
      C <- 1 - T / (N^3 - N)
      D <- rs - ns * (N + 1) / 2
      H <- (12 / (N * (N + 1))) * sum(D^2 / ns) / C
      emit(case, "kruskal_wallis.h", H)
      emit(case, "kruskal_wallis.h_kruskal_test", unname(kt$statistic))
      emit(case, "kruskal_wallis.p", kt$p.value)
      emit(case, "kruskal_wallis.epsilon_squared", H / (N - 1))
    }
    emit(case, "note.exact_not_given_ties", 0)
    emit(case, "note.exact_not_given_size", 0)
  }
  emit(case, "note.group_below_five", as.numeric(any(ns < 5)))
}

refuse <- function(case, code, params) {
  emit(case, "refused", code)
  for (p in names(params)) emit(case, paste0("refused.", p), params[[p]])
}

set.seed(80601)
# Distinct values: a shuffled grid of thousandths, so no two are tied.
distinct <- function(n, from = 0, step = 0.137) from + step * sample.int(n * 3, n)

# ---- two groups ----------------------------------------------------------
y <- c(num(c(1.2, 3.4, 2.2, 5.9, 4.1, 0.7)), num(c(6.3, 2.8, 7.7, 5.1, 8.4, 3.9, 6.8)))
d <- write_data("mw_small", y, c(rep("a", 6), rep("b", 7)))
add_case("mw_small", "data_mw_small.csv", "y", "g", NULL, c()); analyse("mw_small", d)

# 1 and 4 against 2 and 3: U1 = 2 = n1 n2 / 2, so twice the smaller tail
# is 4 / 3 and the exact p is 1.
d <- write_data("mw_centre", c("1", "4", "2", "3"), c("a", "a", "b", "b"))
add_case("mw_centre", "data_mw_centre.csv", "y", "g", NULL, c()); analyse("mw_centre", d)

y <- c("3", "5", "5", "7", "2", "9", "5", "4", "7", "7", "8", "6", "9", "10", "5", "8")
d <- write_data("mw_ties", y, c(rep("lo", 7), rep("hi", 9)))
add_case("mw_ties", "data_mw_ties.csv", "y", "g", NULL, c()); analyse("mw_ties", d)

v <- distinct(98, 10)
stopifnot(!anyDuplicated(num(v)))
d <- write_data("mw_49_49", num(v), c(rep("p", 49), rep("q", 49)))
add_case("mw_49_49", "data_mw_49_49.csv", "y", "g", NULL, c()); analyse("mw_49_49", d)

v <- distinct(60, 5)
stopifnot(!anyDuplicated(num(v)))
d <- write_data("mw_50_10", num(v), c(rep("big", 50), rep("small", 10)))
add_case("mw_50_10", "data_mw_50_10.csv", "y", "g", NULL, c()); analyse("mw_50_10", d)

v <- distinct(31, 1)
stopifnot(!anyDuplicated(num(v)))
d <- write_data("mw_one_vs_thirty", num(v), c("solo", rep("many", 30)))
add_case("mw_one_vs_thirty", "data_mw_one_vs_thirty.csv", "y", "g", NULL, c())
analyse("mw_one_vs_thirty", d)

# 100,000 rows: values 1 to 200, the second group shifted up a little.
yv <- 1:200
c1 <- 250 + ((yv * 37) %% 11) * 10
c2 <- 250 + (((yv + 9) * 37) %% 11) * 10 + (yv > 100) * 4
scale <- 50000 / c(sum(c1), sum(c2))
c1 <- round(c1 * scale[1]); c2 <- round(c2 * scale[2])
d <- write_counts("mw_large", c(yv, yv), c(rep("A", 200), rep("B", 200)), c(c1, c2))
add_case("mw_large", "counts_mw_large.csv", "y", "g", NULL, c()); analyse("mw_large", d)

# ---- three or more groups -----------------------------------------------
y <- num(c(2.9, 3.0, 2.5, 2.6, 3.2, 3.8, 2.7, 4.0, 2.4, 2.8, 3.4, 3.7, 2.2, 2.0))
d <- write_data("kw_small", y, c(rep("x", 5), rep("y", 4), rep("z", 5)))
add_case("kw_small", "data_kw_small.csv", "y", "g", NULL, c()); analyse("kw_small", d)

y <- as.character(c(1, 2, 2, 3, 3, 3, 4, 2, 3, 3, 4, 4, 5, 1, 3, 4, 5, 5, 5, 2, 4))
d <- write_data("kw_ties", y, c(rep("u", 7), rep("v", 6), rep("w", 8)))
add_case("kw_ties", "data_kw_ties.csv", "y", "g", NULL, c()); analyse("kw_ties", d)

# Fifty groups, df 49, five values each.
gl <- sprintf("k%02d", 0:49)
v <- round(sapply(0:249, function(i) (i %/% 5) * 0.11 + ((i * 7919) %% 97) / 10), 3)
d <- write_data("kw_50", num(v), rep(gl, each = 5))
add_case("kw_50", "data_kw_50.csv", "y", "g", NULL, c()); analyse("kw_50", d)

# 100,000 rows near the null: three groups of nearly one distribution over
# the values 1 to 100, where kruskal.test's form loses digits.
yv <- 1:100
base <- 330 + ((yv * 13) %% 7)
cnt <- c(base, base + (yv == 50), base + (yv == 51))
d <- write_counts("kw_large", rep(yv, 3), rep(c("G1", "G2", "G3"), each = 100), cnt)
add_case("kw_large", "counts_kw_large.csv", "y", "g", NULL, c()); analyse("kw_large", d)

# ---- every value equal ---------------------------------------------------
d <- write_data("all_equal_two", rep("4.5", 9), c(rep("a", 4), rep("b", 5)))
add_case("all_equal_two", "data_all_equal_two.csv", "y", "g", NULL, c()); analyse("all_equal_two", d)
d <- write_data("all_equal_three", rep("7", 12), rep(c("a", "b", "c"), 4))
add_case("all_equal_three", "data_all_equal_three.csv", "y", "g", NULL, c())
analyse("all_equal_three", d)

# ---- the groups' order ---------------------------------------------------
# 2 and 10 as numbers: code-point order puts 10 first, so 10 is the first
# group and the signs of z and of the rank-biserial correlation are its.
y <- num(c(4.1, 5.2, 3.3, 6.4, 5.5, 7.1, 1.1, 2.2, 3.4, 0.5, 2.6, 1.7, 2.9))
d <- write_data("numeric_2_10", y, c(rep("2", 6), rep("10", 7)))
add_case("numeric_2_10", "data_numeric_2_10.csv", "y", "g", NULL, c()); analyse("numeric_2_10", d)

# Code-point order is not alphabetical: upper case first, then lower case,
# then letters outside ASCII (Ä U+00C4, É U+00C9, Ö U+00D6, é U+00E9).
gl <- c("Zebra", "apple", "Äpfel", "éclair", "Ölung", "banana")
v <- distinct(30, 2)
d <- write_data("codepoint_text", num(v), rep(gl, each = 5))
add_case("codepoint_text", "data_codepoint_text.csv", "y", "g", NULL, c())
analyse("codepoint_text", d)

# Four levels, two ticked (Mann-Whitney) and three ticked (Kruskal-Wallis).
y <- num(c(5.5, 6.1, 4.2, 7.3, 3.1, 2.7, 4.4, 3.9, 8.8, 9.1, 7.7, 8.2, 1.0, 1.9, 2.3, 0.8))
gl <- rep(c("d1", "d2", "d3", "d4"), each = 4)
d <- write_data("four_levels", y, gl)
add_case("four_levels_two", "data_four_levels.csv", "y", "g", c(1, 3), c())
analyse("four_levels_two", d, levels = c(1, 3))
add_case("four_levels_three", "data_four_levels.csv", "y", "g", c(0, 1, 3), c())
analyse("four_levels_three", d, levels = c(0, 1, 3))

# ---- missing codes and empty cells --------------------------------------
# -9 and 99 are codes of the outcome; a group cell of 99 is a level, never a
# code (codes apply to the outcome only).
y <- c(num(c(2.1, 3.5, 4.2, 1.8, 5.0, 2.9, 6.6, 3.3)), "-9", "99", "99", num(c(4.4, 5.8)), "-9")
g <- c("m", "m", "m", "m", "n", "n", "n", "n", "m", "n", "m", "99", "99", "99")
d <- write_data("codes_outcome", y, g)
add_case("codes_outcome", "data_codes_outcome.csv", "y", "g", NULL, c(-9, 99))
analyse("codes_outcome", d, c(-9, 99))

y <- c(num(c(1.5, 2.5, 3.5, 4.5, 5.5, 6.5, 7.5, 0.5, 8.5)), NA, NA, num(c(9.5, 10.5)), NA)
g <- c("s", "t", "s", "t", "s", "t", "s", "t", NA, "s", "t", NA, "t", NA)
d <- write_data("empty_both", y, g)
add_case("empty_both", "data_empty_both.csv", "y", "g", NULL, c()); analyse("empty_both", d)

# ---- refusals, one for each check ----------------------------------------
d <- write_data("refuse_base", num(c(1, 2, 3, 4, 5, 6)), c("a", "b", "c", "a", "b", "c"))
add_case("refuse_code_not_finite", "data_refuse_base.csv", "y", "g", NULL, c("NaN"))
refuse("refuse_code_not_finite", "stats.ranks.missing_code_not_finite", list(index = 0))
add_case("refuse_unknown_column", "data_refuse_base.csv", "nosuch", "g", NULL, c())
refuse("refuse_unknown_column", "stats.ranks.unknown_column", list(column = "outcome"))
add_case("refuse_same_column", "data_refuse_base.csv", "g", "g", NULL, c())
refuse("refuse_same_column", "stats.ranks.same_column", list())
add_case("refuse_level_out_of_range", "data_refuse_base.csv", "y", "g", c(0, 5), c())
refuse("refuse_level_out_of_range", "stats.ranks.level_out_of_range", list(index = 5, limit = 2))
add_case("refuse_level_repeated", "data_refuse_base.csv", "y", "g", c(1, 1, 2), c())
refuse("refuse_level_repeated", "stats.ranks.level_repeated", list(index = 1))
add_case("refuse_too_few_levels", "data_refuse_base.csv", "y", "g", c(2), c())
refuse("refuse_too_few_levels", "stats.ranks.too_few_levels", list(count = 1))

d <- write_data("refuse_text", c("1", "2", "x", "4", "abc"), c("a", "b", "a", "b", "a"))
add_case("refuse_outcome_text", "data_refuse_text.csv", "y", "g", NULL, c())
refuse("refuse_outcome_text", "stats.ranks.outcome_holds_text", list(column = "outcome", count = 2))

# An infinity written out is a non-finite number to Gaply (stats_l1's column
# issue), refused before any text is counted.
d <- write_data("refuse_infinite", c("1", "2", "Inf", "4", "x"), c("a", "b", "a", "b", "a"))
add_case("refuse_outcome_non_finite", "data_refuse_infinite.csv", "y", "g", NULL, c())
refuse("refuse_outcome_non_finite", "stats.ranks.outcome_non_finite", list(column = "outcome", count = 1))

d <- write_data("refuse_one_level", num(1:6), rep("only", 6))
add_case("refuse_one_level", "data_refuse_one_level.csv", "y", "g", NULL, c())
analyse("refuse_one_level", d, refusal = TRUE)

d <- write_data("refuse_51_levels", num(0:101), sprintf("L%02d", 0:101 %% 51))
add_case("refuse_51_levels", "data_refuse_51_levels.csv", "y", "g", NULL, c())
analyse("refuse_51_levels", d, refusal = TRUE)

# Level "b" has rows, but every outcome there is empty or coded: an included
# group with no value.
d <- write_data("refuse_group_empty", c(num(c(1, 2, 3)), NA, "-9", num(c(4, 5))),
                c("a", "a", "c", "b", "b", "c", "a"))
add_case("refuse_group_empty", "data_refuse_group_empty.csv", "y", "g", NULL, c(-9))
analyse("refuse_group_empty", d, c(-9), refusal = TRUE)

stamp <- c("# written by: /usr/local/bin/Rscript make_ranks_fixtures.R",
           sprintf("# %s, base R stats only", R.version.string))
writeLines(c(stamp, "case\tfile\toutcome\tgroup\tlevels\tmissing_codes", cases), "cases.tsv",
           useBytes = TRUE)
writeLines(c(stamp, "case\tkey\tvalue", expected), "expected.tsv", useBytes = TRUE)
cat(sprintf("%d cases, %d expected values\n", length(cases), length(expected)))
